package ultra.downloads;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28) @LooperMode(LooperMode.Mode.PAUSED)
public class NativeBrowseBindingTest{
 Object allocate(String name)throws Exception{Class<?> c=Class.forName("sun.misc.Unsafe");Field f=c.getDeclaredField("theUnsafe");f.setAccessible(true);return c.getMethod("allocateInstance",Class.class).invoke(f.get(null),Class.forName(name));}
 void field(Object o,String owner,String name,Object value)throws Exception{Field f=Class.forName(owner).getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
 @Test public void exactNativeBrowseModelReadsDisplayedPlaylist()throws Exception{Object page=allocate("jds"),model=Class.forName("kiu").getConstructor().newInstance(),command=Class.forName("amay").getMethod("a",String.class).invoke(null,"VLPLcorrectPlaylist");field(model,"kiw","e",command);field(page,"jde","s",model);assertEquals("VLPLcorrectPlaylist",NativePages.current(page));assertFalse(NativePages.ready(page));field(model,"kiw","g",new Object());assertTrue(NativePages.ready(page));Object second=Class.forName("amay").getMethod("a",String.class).invoke(null,"MPREcorrectAlbum");field(model,"kiw","e",second);assertEquals("MPREcorrectAlbum",NativePages.current(page));}
 @Test public void usesActualObfuscatedFragmentManagerList()throws Exception{Object manager=allocate("et"),store=allocate("fg");field(store,"fg","a",new ArrayList<>());field(manager,"et","c",store);assertTrue(Class.forName("et").getMethod("l").invoke(manager) instanceof List);NativePages.visit(manager,new HashSet<>(),0);}
 @Test public void malformedObserverCannotEscape(){NativePages.attach(new Object());NativePages.detach(new Object());NativePages.stop();assertTrue(NativePages.bindings.isEmpty());}
 @Test public void startAndPauseDoNotUseGlobalLayoutListener()throws Exception{Activity host=Robolectric.buildActivity(Activity.class).setup().get();NativePages.start(host);assertTrue(NativePages.running);Shadows.shadowOf(Looper.getMainLooper()).idle();NativePages.stop();assertFalse(NativePages.running);assertNull(NativePages.host.get());host.finish();}
}
